// 1. 抹除 webdriver 迹象，并修复原型链（防止大厂用 toString 探测伪造）
const newProto = Object.create(Object.getPrototypeOf(navigator));
Object.defineProperty(newProto, 'webdriver', { get: () => undefined });
Object.setPrototypeOf(navigator, newProto);

// 2. 伪造完美的 window.chrome 运行环境
window.chrome = {
    runtime: {},
    loadTimes: function() {},
    csi: function() {},
    app: { isInstalled: false, InstallState: { DISABLED: 'disabled', INSTALLED: 'installed', NOT_INSTALLED: 'not_installed' }, getInstallState: function() {}, getDetails: function() {} }
};

// 3. 伪造标准的语言和权限
Object.defineProperty(navigator, 'languages', { get: () => ['zh-CN', 'zh', 'en'] });
Object.defineProperty(navigator, 'plugins', { get: () => [1, 2, 3, 4, 5] }); // 假装装了插件

// 4. 关键：伪造 WebGL 绘图上下文（防浏览器指纹碰撞）
// 很多风控会默默在后台画一个隐形图形，看你的显卡驱动是不是 HeadlessChrome
const getParameter = WebGLRenderingContext.prototype.getParameter;
WebGLRenderingContext.prototype.getParameter = function(parameter) {
    if (parameter === 37445) return 'Intel Inc.';
    if (parameter === 37446) return 'Intel(R) Iris(R) Xe Graphics Direct3D11 vs_5_0 ps_5_0';
    return getParameter.apply(this, arguments);
};

// 5. 修复 window.navigator.permissions
const originalQuery = window.navigator.permissions.query;
window.navigator.permissions.query = (parameters) => (
    parameters.name === 'notifications' ?
    Promise.resolve({ state: Notification.permission }) :
    originalQuery(parameters)
);